    val MAP: Map<String, DuaText> = mapOf(
        "dua_eid_takbeer" to DuaText("ईदाक वचपी रस्त्यार तकबीर", "अल्लाह सगळ्यांत व्हड, अल्लाह सगळ्यांत व्हड, अल्लाह सोडून देव ना, आनी अल्लाह सगळ्यांत व्हड, अल्लाह सगळ्यांत व्हड, आनी सगळ्यो तोखणाय अल्लाहाक आसा.", "चंद्रभूंयेच्या रातीं सावन ईद-उल-फित्र प्रार्थना मेरेन, खास करून ईदच्या मळार वचतना.", "कुराणान आज्ञा दिल्याः'तुमी मेजणी पुराय करची आनी अल्लाहचें म्हानपण जाहीर करचें'(अल-बकारा 2:185). इब्न मसूद (आर. ए.) हाणें हो तकबीर सांगलें."),
        "dua_ahsin_aqibatana" to DuaText("सगळ्या बाबतींत आमची शेवट बरी कर", "हे अल्लाह, सगळ्याच बाबतींत आमची शेवट बरी कर, आनी ह्या संवसारांत अपमान आनी आख़िरतांत ख्यास्त जावची न्हय अशी आमची राखण कर.", "दरेक बाबतींत बरो परिणाम मेळपाक.", "जो कोण हो दुआ करता आनी खटलो चल्लो जावचे पयलीं मरता (खटल्या पसून सुरक्षीत)."),
        "dua_fadlika_wa_rahmatik" to DuaText("हांव तुजी कृपा आनी दया मागता.", "हे अल्लाह, हांव तुजी कृपा आनी दया मागता, कारण तुज्या शिवाय कोणूच ताचे मालक ना.", "तरतूद आनी दया मागतना.", "अन्न नाशिल्ल्यान पैगंबर सल्ल्याह अलियाह वसलमा कडेन अतिथी आयले; ताणें ही दुआ केली, आनी मागीर भेटवस्तू आयली."),
        "dua_allahu_akbar_kabira_2696" to DuaText("बेडूईनाक शिकयल्ल्या शब्द", "अल्लाह सोडून कोणाकूच पुजा करपाचो अधिकार ना, एकलो, भागीदार नासतना. अल्लाह सगळ्यांत व्हड, खूब, अल्लाहाक खूब तोखणाय आसा; जगाचो स्वामी अल्लाहाक तोखणाय आसा; आनी सर्वशक्तिमान, तत्वज्ञ अल्लाह सोडून हेर कोणूच सामर्थ्य वा शक्ती ना.", "एक बेडूईनाक शिकयल्ल्या धिक्र आनी दुआ ह्या सगळ्या गजालींचो एक व्यापक वाक्यांश.", "हाचे उपरांत ताका'अल्लाहुम्माघफिर ली वारहमनी वाहदिनी वारझुकनी \"म्हणपाक शिकयलें."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("हांवें पयलीं आनी उपरांत जें धाडलें तें माफ कर.", "हे अल्लाह, हांवें आदीं आनी उपरांत केल्ल्या पापांक, हांवें गुपीतपणान कितें केलें आनी हांवें उघडपणान कितें केलें, म्हज्या अतिरेकांक, आनी म्हजे परस कितें बरें कळटा तें म्हाका माफ कर. तूं मुखार हाडपी आनी फाटीं घालपी तूंच; तूं सोडून देव ना.", "ताशाहहुद आनी सलावा उपरांत, सलामा पयलीं.", "पैगंबर सल्ल्याह अलियाह वसलमान प्रार्थनेच्या निमाण्या वेळार, ताशाहहुद आनी सलमा मदीं हें पठण केलें."),
        "dua_jiddi_wa_hazli" to DuaText("म्हज्या गंभीरतायेक आनी म्हज्या विनोदाक माफ कर.", "हे अल्लाह, हांवें गंभीरपणान आनी विनोदांत, चुकून आनी जाणूनबुजून केल्ल्या पापांक म्हाका माफ कर-आनी तें सगळें म्हजे भितर आसा.", "जाणिल्ल्या आनी अज्ञात आशिल्ल्या सगळ्या प्रकारच्या पापांखातीर क्षमा.", "पैगंबर सल्ल्याह अल्लीह वसलमाचो एक व्यापक इस्तिफफर."),
        "dua_rising_ruku_mil" to DuaText("रुकू उपरांत-स्वर्ग भरपाची तोखणाय कर", "म्हज्या देवा, आकाश भरप, धर्तीर भरप आनी ताचे उपरांत तूं कितेंय भरपाक सोदता तें सगळें तोखणाय तुजेच.", "रुकू सावन वयर सरल्या उपरांत'रब्बाना लकल-हमद \"वांगडा.", "पैगंबर सल्ल्याह अलियाह वसलमान रुकू वयल्यान वयर सरतना हें सांगलें."),
        "dua_istiftah_kabira" to DuaText("अल्लाह सगळ्यांत व्हड, भरपूर तोखणाय जाता.", "अल्लाह सगळ्यांत व्हड, खूब, अल्लाहाक खूब तोखणाय जाता; आनी सकाळ सांज अल्लाहाक गौरव आसा.", "प्रार्थना सुरू करतना (उक्तें स्तुतीचो एक प्रकार).", "पैगंबर सल्लल्लाह अलीह वस्लमान सांगलेंः ताचे खातीर स्वर्गाचीं दारां उक्तीं केलीं."),
        "dua_q_ashku_bathhi" to DuaText("याकूब (अ. स.)-हांव फकत अल्लाहाक कागाळ करता", "हांव म्हज्या दुख्ख आनी दुख्ख हांची कागाळ फकत अल्लाहाक करता.", "खोल दुख्खी आनी वेगळेपणांत.", "याकूब (ए. एस.) हाणें युसूफा (ए. एस.) हाचे पसून वेगळे जावन हें सांगलें."),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाह हो सगळ्यांत बरो राखणदार", "अल्लाह सगळ्यांत बरो राखणदार आनी तो दयाळू लोकां मदीं सगळ्यांत दयाळू आसा.", "भुरग्यांक वा मोग्यांक भोंवडेक धाडतना.", "याकूब (अ. स.) हाणें आपल्या पुताक अल्लाहाक सोपयतान हें सांगलें."),
        "dua_q_aqraba_rashada" to DuaText("म्हजो प्रभू म्हाका उजवे वटेन लागीं वचपाक मार्गदर्शन करचो.", "घडये म्हजो प्रभू म्हाका हाचे परस योग्य आचरणाक लागीं आशिल्ल्या गजालींचेर मार्गदर्शन करतलो.", "खंयच्याय बाबतींत बरो मार्ग सोदतना.", "पैगंबर सल्ल्याह अलियाह वसलमाक विसरून हें सांगपाक सांगलें."),
        "dua_q_sawa_as_sabil" to DuaText("मुसाचो दुआ (ए. एस.)-म्हाका योग्य मार्ग दाखय", "घडये म्हजो प्रभू म्हाका योग्य मार्ग दाखयतलो.", "नव्या प्रवासाक वा अपरिचित रस्त्यार भायर सरतना.", "मदयना वटेन वळतना मुसा (ए. एस.) हें सांगलें."),
        "dua_q_not_among_wrongdoers" to DuaText("म्हाका चुकीच्या लोकां मदीं दवरूं नाकात", "म्हज्या देवा, म्हाका अन्याय करपी लोकां मदीं दवरचो न्हय.", "एक दुआ अल्लाहाक एकाक अपराधी पसून वेगळो दवरपाक मागता.", "एक दुआ अल्लाहाक एकाक अपराधी पसून वेगळो दवरपाक मागता."),
        "dua_q_do_not_make_us_trial" to DuaText("आमचेर खटलो चलोवचो न्हय", "म्हज्या प्रभू, अविश्वास्यांक आमची परिक्षा दिवची न्हय, आनी आमचो प्रभू, आम्हांक माफ कर. तूं खरेंच सर्वशक्तिमान, तत्ववान आसा.", "इब्राहिम (अ. स.) आनी ताच्या साथीदारांचो दुआ.", "इब्राहिम (अ. स.) आनी ताच्या साथीदारांचो दुआ."),
        "dua_morning_witness" to DuaText("सकाळचो तौहीदाचो साक्षीदार", "हे अल्लाह, हांव सकाळीं पावलां आनी तुका, तुज्या सिंहासनाचे वाहकांक, तुज्या देवदूतांक आनी तुज्या सगळ्या सृष्टीक तूंच अल्लाह आसा, तुज्या शिवाय कोणूच देव ना, एकलो, भागीदार नासतना, आनी मुहंमद सल्लाह अल्लीह इस्लाम तुजो सेवक आनी संदेशवाहक आसा हाची साक्ष दिवपाखातीर हाकलून दिता.", "सकाळीं चार फावटीं अशें सांगपाचो उल्लेख कथेंत आसा.", "सकाळीं चार फावटीं अशें सांगपाचो उल्लेख कथेंत आसा."),
        "dua_evening_witness" to DuaText("तौहिदाचो सांजवेळचो साक्षीदार", "हे अल्लाह, हांव सांजवेळार पावलां आनी तुका, तुज्या सिंहासनाचे वाहकांक, तुज्या देवदूतांक आनी तुज्या सगळ्या सृष्टीक, तूंच अल्लाह आसा, तुज्या शिवाय कोणूच देव ना, एकलो, भागीदार नासतना, आनी मुहंमद सल्लाह अल्लीह इस्लाम तुजो सेवक आनी संदेशवाहक आसा हाची साक्ष दिवपाखातीर हाकलून दिता.", "सांजे चार फावटीं अशें सांगपाचो उल्लेख कथेंत आसा.", "सांजे चार फावटीं अशें सांगपाचो उल्लेख कथेंत आसा."),
        "dua_morning_blessing" to DuaText("सकाळीं आशीर्वादां खातीर उपकार", "हे अल्लाह, आयज सकाळीं म्हाका वा तुज्या सृष्टींतलें खंयचेंय आशीर्वाद फकत तुज्या कडल्यान मेळ्ळां, भागीदार नासतना; देखून सगळी तोखणाय आनी उपकार तूंच.", "अल्लाहच्या आशीर्वादाक उपकार मानपी सकाळचो दिकर.", "अल्लाहच्या आशीर्वादाक उपकार मानपी सकाळचो दिकर."),
        "dua_evening_blessing" to DuaText("सांज आशीर्वादां खातीर उपकार", "हे अल्लाह, आयज सांज म्हाका वा तुज्या सृष्टींतलें खंयचेंय आशीर्वाद फकत तुज्या कडल्यान मेळ्ळां, भागीदार नासतना; देखून सगळी तोखणाय आनी उपकार तूंच.", "अल्लाहच्या आशीर्वादाक उपकार मानपी सांजवेळ.", "अल्लाहच्या आशीर्वादाक उपकार मानपी सांजवेळ."),
